sys_script_include.script:
var Cisco_Secure_Access_App_Approval_Processing_Public_Apps = Class.create();
Cisco_Secure_Access_App_Approval_Processing_Public_Apps.prototype = {
	initialize: function () { },
	process: function () {
		try {
			gs.info("[Cisco Secure Access - PUB] Starting public app approval processing...");

			// Step 1: Find latest incident for each app_id
			var incGR = new GlideRecord('incident');
			incGR.addQuery('short_description', 'CONTAINS', 'App Approval Required');
			incGR.orderByDesc('sys_created_on');
			incGR.query();

			var latestByAppId = {};
			while (incGR.next()) {
				var appIdMatch = incGR.description ? incGR.description.match(/App ID:\s*(\S+)/) : null;
				if (!appIdMatch) continue;
				var appId = appIdMatch[1].trim();
				if (!latestByAppId[appId]) {
					latestByAppId[appId] = incGR.getUniqueValue();
				}
			}

			// Step 2: Update discovered app approval_status from latest incident
			for (var appId in latestByAppId) {
				var inc = new GlideRecord('incident');
				if (!inc.get(latestByAppId[appId])) continue;
				var closeCode = (inc.close_code || inc.resolution_code || "").toLowerCase();
				gs.info("[DEBUG] App ID=" + appId + " closeCode=" + closeCode);
				var decision = "";
				if (closeCode.indexOf("approved") !== -1) decision = "Allow";
				else if (closeCode.indexOf("rejected") !== -1) decision = "Block";
				if (!decision) continue;

				// Update discovered app record
				var appGR = new GlideRecord('u_cisco_sceure_access_discovered_appliaction');
				appGR.addQuery('u_app_id', appId);
				appGR.query();
				if (appGR.next()) {
					appGR.u_approval_status = decision;
					appGR.u_status = inc.state == 7 ? 'Closed' : 'Resolved';
					appGR.u_label = "Reviewed";
					appGR.u_notes = ((inc.resolution_notes || inc.close_notes || "").trim()) +
						" | Processed via incident " + inc.number;
					appGR.u_send_alert = "Yes";
					appGR.update();
					gs.info("[Cisco Secure Access - PUB] Updated app " + appId + " approval_status to " + decision + " and status to " + appGR.u_status);
				}
			}

			// Step 3: Insert into CMDB Application table
			var appGR2 = new GlideRecord('u_cisco_sceure_access_discovered_appliaction');
			appGR2.query();

			var total = 0, inserted = 0, skipped = 0;
			while (appGR2.next()) {
				total++;
				if (!appGR2.u_approval_status || (appGR2.u_approval_status != "Allow" && appGR2.u_approval_status != "Block")) {
					gs.info("[Cisco Secure Access - PUB] Skipping app_id=" + appGR2.u_app_id + " due to approval_status=" + appGR2.u_approval_status);
					continue;
				}

				// Check if already in CMDB Application table
				var cmdbCheck = new GlideRecord("u_cmdb_ci_application");
				cmdbCheck.addQuery('u_application_id', appGR2.u_app_id);
				cmdbCheck.query();
				if (cmdbCheck.next()) {
					gs.info("[CMDB SKIP] App ID=" + appGR2.u_app_id + " already exists in Application. Skipping.");
					skipped++;
					continue;
				}

				// Insert
				var cmdbGR = new GlideRecord("u_cmdb_ci_application");
				cmdbGR.initialize();
				cmdbGR.u_application_id = appGR2.u_app_id;
				cmdbGR.name = appGR2.u_app_name.toString().trim();
				cmdbGR.u_approval_status = appGR2.u_approval_status;
				cmdbGR.short_description = appGR2.u_label;
				cmdbGR.u_status = appGR2.u_status;
				cmdbGR.first_discovered = appGR2.u_first_detected;
				cmdbGR.discovery_source = appGR2.u_discovered_in;
				cmdbGR.sys_created_on = appGR2.sys_created_on;
				cmdbGR.sys_created_by = appGR2.sys_created_by;
				cmdbGR.sys_updated_on = appGR2.sys_updated_on;
				cmdbGR.sys_updated_by = appGR2.sys_updated_by;
				cmdbGR.public_or_private = "Public";
				var sysId = cmdbGR.insert();
				if (sysId) {
					gs.info("[CMDB INSERT] App ID=" + appGR2.u_app_id + " inserted into Application. Sys ID=" + sysId);
					inserted++;
				} else {
					gs.warn("[CMDB INSERT] Failed to insert App ID=" + appGR2.u_app_id + " into Application.");
				}
			}

			gs.info("[Cisco Secure Access - PUB] Summary: Total processed: " + total + ", Inserted: " + inserted + ", Skipped: " + skipped);

			// Step 4: Fetch application details from SSE API using REST Message record
			var apiApps = [];
			try {
				var token = new CiscoSecureAccessGetToken().getLatestAccessToken();
				var restMsg = new sn_ws.RESTMessageV2('Cisco Secure Access Get Numeric APP ID', 'Default GET');
				restMsg.setRequestHeader("Authorization", "Bearer " + token);
				restMsg.setRequestHeader("Accept", "application/json");
				gs.info("[Cisco Secure Access - PUB] Executing REST Message: Cisco Secure Access Get Numeric APP ID");
				var response = restMsg.execute();
				var responseBody = response.getBody();
				gs.info("[Cisco Secure Access - PUB] SSE API raw response: " + responseBody);
				var apiData = JSON.parse(responseBody);

				// Try to find applications array, or treat as array if root is array
				if (apiData && apiData.applications) {
					apiApps = apiData.applications;
				} else if (Array.isArray(apiData)) {
					apiApps = apiData;
				} else if (apiData && apiData.length && typeof apiData[0] === "object") {
					apiApps = apiData;
				} else {
					gs.warn("[Cisco Secure Access - PUB] No applications found in SSE API response.");
				}
				gs.info("[Cisco Secure Access - PUB] SSE API applications count: " + apiApps.length);
			} catch (ex) {
				gs.error("[Cisco Secure Access - PUB] Error fetching SSE applications: " + ex.message);
			}

			// Helper to get numeric app id from SSE API by name (normalize whitespace/case)
			function getSseAppId(appName) {
				var normName = appName.replace(/\s+/g, ' ').trim().toLowerCase();
				for (var i = 0; i < apiApps.length; i++) {
					var apiName = (apiApps[i].name || "").replace(/\s+/g, ' ').trim().toLowerCase();
					if (apiName === normName) {
						gs.info("[Cisco Secure Access - PUB] Matched app name '" + appName + "' to SSE app id: " + apiApps[i].id);
						return apiApps[i].id; // integer
					}
				}
				gs.warn("[Cisco Secure Access - PUB] No SSE app id found for app name: " + appName);
				return null;
			}

			// Step 5: Build Allow/Block lists using SSE numeric app IDs, matching by app name from discovered application table
			var allowAppIds = [], blockAppIds = [];
			var allowAppNames = [], blockAppNames = [];
			var appGR2 = new GlideRecord('u_cisco_sceure_access_discovered_appliaction');
			appGR2.query();
			while (appGR2.next()) {
				var appName = appGR2.u_app_name.toString().trim();
				var decision = appGR2.u_approval_status;
				var sseAppId = getSseAppId(appName); // Match by name from SSE API payload
				gs.info("[Cisco Secure Access - PUB] Checking discovered app: " + appName + " | SSE App ID: " + sseAppId + " | Approval Status: " + decision);
				if (!sseAppId) continue; // skip if not found in SSE API
				if (decision == "Allow") {
					allowAppIds.push(sseAppId);
					allowAppNames.push(appName);
				} else if (decision == "Block") {
					blockAppIds.push(sseAppId);
					blockAppNames.push(appName);
				}
			}
			gs.info("[Cisco Secure Access - PUB] Allow App IDs: " + JSON.stringify(allowAppIds));
			gs.info("[Cisco Secure Access - PUB] Block App IDs: " + JSON.stringify(blockAppIds));
			gs.info("[Cisco Secure Access - PUB] Allow App Names: " + JSON.stringify(allowAppNames));
			gs.info("[Cisco Secure Access - PUB] Block App Names: " + JSON.stringify(blockAppNames));

			// Step 6: Fetch active application lists
			var allowListId = "", blockListId = "";
			var allowListName = "", blockListName = "";
			var allowListIsDefault = false, blockListIsDefault = false;
			var appListGR = new GlideRecord('u_cisco_secure_access_application_list');
			appListGR.addQuery('u_active_status', 'Active');
			appListGR.query();
			while (appListGR.next()) {
				var groupFor = appListGR.u_resource_group_for + "";
				if (groupFor.toLowerCase().includes("allow")) {
					allowListId = appListGR.u_application_list_id + "";
					allowListName = appListGR.u_application_list_name + "";
					allowListIsDefault = (appListGR.u_is_default == "true");
				}
				if (groupFor.toLowerCase().includes("block")) {
					blockListId = appListGR.u_application_list_id + "";
					blockListName = appListGR.u_application_list_name + "";
					blockListIsDefault = (appListGR.u_is_default == "true");
				}
			}

			// Step 7: Build payloads
			var allowPayload = {
				applicationIds: allowAppIds,
				applicationListName: allowListName,
				isDefault: allowListIsDefault
			};
			var blockPayload = {
				applicationIds: blockAppIds,
				applicationListName: blockListName,
				isDefault: blockListIsDefault
			};
			gs.info("[Cisco Secure Access - PUB] Allow Payload: " + JSON.stringify(allowPayload));
			gs.info("[Cisco Secure Access - PUB] Block Payload: " + JSON.stringify(blockPayload));

			// Step 8: Send REST messages to update application lists
			function sendApplicationListUpdate(listId, payload, type) {
				if (!payload.applicationIds || payload.applicationIds.length === 0) {
					gs.info("[Cisco Secure Access - PUB] No " + type + " apps to send. Skipping REST call.");
					return;
				}
				try {
					var restMsg = new sn_ws.RESTMessageV2('Cisco Secure Access Application List', 'Update Application List');
					restMsg.setHttpMethod('PUT');
					restMsg.setRequestHeader("Content-Type", "application/json");
					restMsg.setRequestHeader("Accept", "application/json");
					var token = new CiscoSecureAccessGetToken().getLatestAccessToken();
					restMsg.setRequestHeader("Authorization", "Bearer " + token);
					restMsg.setStringParameterNoEscape('EnterApplicationListID', listId);
					restMsg.setRequestBody(JSON.stringify(payload));
					gs.info("[Cisco Secure Access - PUB] Sending REST payload (" + type + "): " + JSON.stringify(payload));
					var response = restMsg.execute();
					gs.info("[Cisco Secure Access - PUB] REST Response (" + type + ") for listId=" + listId +
						": Status=" + response.getStatusCode() + " | Body=" + response.getBody());
				} catch (ex) {
					gs.error("[Cisco Secure Access - PUB] REST call exception for " + type + ": " + ex.message);
				}
			}

			if (allowListId && allowAppIds.length > 0) sendApplicationListUpdate(allowListId, allowPayload, "Allow");
			if (blockListId && blockAppIds.length > 0) sendApplicationListUpdate(blockListId, blockPayload, "Block");

			gs.info("[Cisco Secure Access - PUB] - Cisco Secure Access  Public App Approval Processing completed.");
		} catch (ex) {
			gs.error("[Cisco Secure Access - PUB] - Error in processing: " + ex.message);
		}
	},

	type: 'Cisco_Secure_Access_App_Approval_Processing_Public_Apps'
};
